using System.Text;
using System.Text.Json;
using Forge.Core;
using Xunit;

namespace Forge.Core.Tests;

/// <summary>
/// Verifies <see cref="JinjaRenderer"/> against Python jinja2 (the reference
/// implementation). Each case in the JinjaRefs data directory is a triple:
/// <c>{name}.tpl</c> (template), <c>{name}.json</c> (context), <c>{name}.txt</c>
/// (expected output, byte-for-byte from jinja2 3.1.6). The references were
/// generated by tests/Forge.Core.Tests/JinjaRefs/README.md's generator script.
/// </summary>
public class JinjaRendererTests
{
    [Theory]
    [InlineData("basic-vars")]
    [InlineData("if-true")]
    [InlineData("if-false")]
    [InlineData("elif-chain")]
    [InlineData("for-loop")]
    [InlineData("for-range")]
    [InlineData("comparison-eq")]
    [InlineData("comparison-ne")]
    [InlineData("arithmetic")]
    [InlineData("string-trim")]
    [InlineData("string-upper")]
    [InlineData("string-lower")]
    [InlineData("list-index")]
    [InlineData("dict-access")]
    [InlineData("nested-if-for")]
    [InlineData("boolean-and-or")]
    [InlineData("not-operator")]
    [InlineData("string-concat")]
    [InlineData("empty-for")]
    [InlineData("unicode")]
    public void Render_MatchesJinja2Reference(string name)
    {
        string template = File.ReadAllText(Path.Combine(TestContext.DataDir, $"{name}.tpl"));
        var context = LoadContext(Path.Combine(TestContext.DataDir, $"{name}.json"));
        string expected = File.ReadAllText(Path.Combine(TestContext.DataDir, $"{name}.txt"), Encoding.UTF8);

        string actual = JinjaRenderer.Render(template, context);

        Assert.Equal(expected, actual);
    }

    [Fact]
    public void Render_UnsupportedConstruct_Throws()
    {
        // namespace() is beyond the supported subset — the renderer must report it
        // as unsupported so callers can fall back to a generic prompt.
        Assert.Throws<JinjaRenderer.JinjaRenderException>(
            () => JinjaRenderer.Render("{% set ns = namespace(x=1) %}{{ ns.x }}", new Dictionary<string, object?>()));
    }

    [Fact]
    public void Render_SyntaxError_Throws()
    {
        Assert.Throws<JinjaRenderer.JinjaRenderException>(
            () => JinjaRenderer.Render("{% if x %}unclosed", new Dictionary<string, object?> { ["x"] = true }));
    }

    // ---- helpers ----

    private static class TestContext
    {
        public static string DataDir = Path.GetFullPath(
            Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "JinjaRefs"));
    }

    private static Dictionary<string, object?> LoadContext(string path)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var result = new Dictionary<string, object?>();
        foreach (var prop in doc.RootElement.EnumerateObject())
            result[prop.Name] = FromJson(prop.Value);
        return result;
    }

    private static object? FromJson(JsonElement el) => el.ValueKind switch
    {
        JsonValueKind.String => el.GetString(),
        // Explicit (object) casts: without them the ternary promotes long to double.
        JsonValueKind.Number => el.TryGetInt64(out long l) ? (object)l : (object)el.GetDouble(),
        JsonValueKind.True => true,
        JsonValueKind.False => false,
        JsonValueKind.Null => null,
        JsonValueKind.Array => el.EnumerateArray().Select(FromJson).ToList(),
        JsonValueKind.Object => el.EnumerateObject()
            .ToDictionary(p => p.Name, p => FromJson(p.Value)),
        _ => throw new InvalidOperationException($"Unsupported JSON value kind {el.ValueKind}"),
    };
}
